create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,name text,avatar_url text,company_name text,phone text,role text not null default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ begin create type public.lead_status as enum ('new','contacted','interested','negotiation','customer','lost'); exception when duplicate_object then null; end $$;
create table if not exists public.leads (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,google_place_id text,name text not null,business_name text,category text,categories jsonb not null default '[]',phone text,international_phone text,website text,address text,street text,number text,neighborhood text,city text,state text,postal_code text,country text,latitude double precision,longitude double precision,rating numeric(2,1),reviews_count integer,business_status text,opening_hours jsonb,maps_url text,photos jsonb,types jsonb,has_website boolean,has_phone boolean,has_whatsapp text not null default 'unknown',status public.lead_status not null default 'new',notes text,source text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_contact_at timestamptz,last_synced_at timestamptz);
create unique index if not exists leads_user_place_uidx on public.leads(user_id,google_place_id) where google_place_id is not null;
create table if not exists public.lead_activities (id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,type text not null,title text not null,description text,metadata jsonb,created_at timestamptz not null default now());
create table if not exists public.lists (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.list_leads (list_id uuid not null references public.lists(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,created_at timestamptz not null default now(),primary key(list_id,lead_id));
create table if not exists public.campaigns (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,objective text,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.campaign_leads (campaign_id uuid not null references public.campaigns(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,status text not null default 'pending',created_at timestamptz not null default now(),primary key(campaign_id,lead_id));
create table if not exists public.tags (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,color text,created_at timestamptz not null default now(),unique(user_id,name));
create table if not exists public.lead_tags (lead_id uuid not null references public.leads(id) on delete cascade,tag_id uuid not null references public.tags(id) on delete cascade,primary key(lead_id,tag_id));
create table if not exists public.searches (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,query text not null,location text,filters jsonb not null default '{}',results_count integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.ai_analyses (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,lead_id uuid references public.leads(id) on delete cascade,type text not null,input jsonb,output jsonb,created_at timestamptz not null default now());
create table if not exists public.exports (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,format text not null,filters jsonb,status text not null default 'queued',file_url text,created_at timestamptz not null default now());
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,plan text not null default 'free',status text not null default 'active',started_at timestamptz not null default now(),expires_at timestamptz,limits jsonb not null default '{}');
create table if not exists public.credit_balances (user_id uuid primary key references auth.users(id) on delete cascade,balance integer not null default 10,updated_at timestamptz not null default now());
create table if not exists public.credit_transactions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount integer not null,reason text not null,metadata jsonb,created_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['profiles','leads','lead_activities','lists','list_leads','campaigns','campaign_leads','tags','lead_tags','searches','notifications','ai_analyses','exports','subscriptions','credit_balances','credit_transactions'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy if not exists "own profiles" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy if not exists "own leads" on public.leads for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own activities" on public.lead_activities for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own lists" on public.lists for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own campaigns" on public.campaigns for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own tags" on public.tags for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own searches" on public.searches for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own notifications" on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own analyses" on public.ai_analyses for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own exports" on public.exports for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own subscriptions" on public.subscriptions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own credits" on public.credit_balances for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy if not exists "own credit transactions" on public.credit_transactions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $fn$
begin insert into public.profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1))); insert into public.credit_balances(user_id,balance) values(new.id,10); insert into public.subscriptions(user_id,plan,status,limits) values(new.id,'free','active','{"daily_searches":5,"ai_analyses":5}'); return new; end; $fn$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
